create function public.link_inventory_barcode(p_item_id uuid,p_code text,p_brand text,p_model text,p_units numeric)
returns uuid language plpgsql security definer set search_path='' as $$
declare site uuid; variant uuid; existing public.inventory_barcodes; result uuid;
begin
  if public.user_role() is distinct from 'admin' then raise exception 'Solo administracion puede asociar codigos'; end if;
  if p_code is null or p_code !~ '^[!-~]{1,128}$' or length(trim(coalesce(p_brand,''))) not between 1 and 80
    or p_model is null or length(p_model)>80 or p_units is null or p_units<=0 or p_units>999999 or p_units<>round(p_units,3) then raise exception 'Revisa codigo, marca y unidades por envase'; end if;
  perform pg_advisory_xact_lock(90714001);
  select i.headquarters_id into site from public.inventory_items i join public.headquarters h on h.id=i.headquarters_id and h.is_active where i.id=p_item_id;
  if not found then raise exception 'Articulo o sede no disponible'; end if;
  insert into public.inventory_variants(item_id,brand,model) values(p_item_id,trim(p_brand),trim(p_model))
    on conflict(item_id,brand,model) do nothing;
  select id into variant from public.inventory_variants where item_id=p_item_id and brand=trim(p_brand) and model=trim(p_model);
  select * into existing from public.inventory_barcodes where headquarters_id=site and code=p_code;
  if found then
    if existing.variant_id<>variant or existing.units_per_pack<>p_units then raise exception 'Este codigo ya esta asociado a otro producto o envase en la sede'; end if;
    return existing.id;
  end if;
  insert into public.inventory_barcodes(headquarters_id,item_id,variant_id,code,units_per_pack)
    values(site,p_item_id,variant,p_code,p_units) returning id into result;
  insert into public.inventory_item_history(item_id,actor_id,event_type,details)
    values(p_item_id,auth.uid(),'barcode_linked',jsonb_build_object('code',p_code,'brand',trim(p_brand),'model',trim(p_model),'units_per_pack',p_units));
  return result;
end $$;

-- One transaction covers all destinations. The receipt identifier survives retries.
create function public.receive_inventory_barcode(p_id uuid,p_barcode_id uuid,p_packs numeric,p_lot_code text,p_expiration date,p_allocations jsonb,p_notes text)
returns numeric language plpgsql security definer set search_path='' as $$
declare b public.inventory_barcodes; v public.inventory_variants; old public.inventory_receipts;
  payload jsonb; total numeric; allocated numeric:=0; part jsonb; amount numeric; lot uuid; balance numeric;
begin
  if public.user_role() is distinct from 'admin' then raise exception 'Solo administracion puede registrar entradas'; end if;
  if p_id is null or p_packs is null or p_packs<=0 or p_packs>99999999999 or p_packs<>trunc(p_packs)
    or p_lot_code is null or length(p_lot_code)>80 or length(trim(coalesce(p_notes,''))) not between 3 and 1000
    or p_allocations is null or jsonb_typeof(p_allocations)<>'array' then raise exception 'Revisa envases, lote, motivo y reparto'; end if;
  if jsonb_array_length(p_allocations) not between 1 and 100 then raise exception 'Elige entre 1 y 100 destinos'; end if;
  payload=jsonb_build_object('barcode_id',p_barcode_id,'packs',p_packs,'lot_code',p_lot_code,'expiration',p_expiration,'allocations',p_allocations,'notes',p_notes);
  perform pg_advisory_xact_lock(90714001);
  select * into old from public.inventory_receipts where id=p_id;
  if found then
    if old.actor_id<>auth.uid() or old.payload<>payload then raise exception 'Identificador reutilizado con datos distintos'; end if;
    return old.balance_after;
  end if;
  select * into b from public.inventory_barcodes where id=p_barcode_id;
  if not found then raise exception 'Codigo no encontrado'; end if;
  if p_expiration is null and exists(select 1 from public.inventory_items i
    join public.inventory_template_fields f on f.template_id=i.template_id
    join public.inventory_fields d on d.id=f.field_id
    where i.id=b.item_id and f.is_required and d.field_key='expiration_date') then
    raise exception 'La ficha de este articulo exige fecha de caducidad para cada lote';
  end if;
  select * into v from public.inventory_variants where id=b.variant_id;
  total=p_packs*b.units_per_pack;
  if total>99999999999.999 or total<>round(total,3) then raise exception 'Cantidad total fuera de rango'; end if;
  for part in select value from jsonb_array_elements(p_allocations) loop
    amount=(part->>'quantity')::numeric;
    if amount is null or amount<=0 or amount>99999999999.999 or amount<>round(amount,3) then raise exception 'Cada destino necesita una cantidad positiva con hasta 3 decimales'; end if;
    allocated=allocated+amount;
  end loop;
  if allocated<>total then raise exception 'El reparto no coincide con las unidades recibidas'; end if;
  insert into public.inventory_stock_lots(item_id,variant_id,code,expiration_date)
    values(b.item_id,b.variant_id,left(v.brand||case when v.model<>'' then ' / '||v.model else '' end,40)||' / '||
      left(coalesce(nullif(trim(p_lot_code),''),'Recepcion '||current_date),34)||' / '||p_id::text,p_expiration) returning id into lot;
  for part in select value from jsonb_array_elements(p_allocations) loop
    balance=public.manage_inventory_stock(gen_random_uuid(),b.item_id,'in',null,lot,
      nullif(part->>'location_id','')::uuid,nullif(part->>'container_id','')::uuid,(part->>'quantity')::numeric,
      'Recepcion '||p_id::text||': '||p_notes);
  end loop;
  insert into public.inventory_receipts(id,item_id,actor_id,payload,balance_after) values(p_id,b.item_id,auth.uid(),payload,balance);
  insert into public.inventory_item_history(item_id,actor_id,event_type,details)
    values(b.item_id,auth.uid(),'barcode_received',payload||jsonb_build_object('variant_id',v.id,'brand',v.brand,'model',v.model,'code',b.code,'units_per_pack',b.units_per_pack,'total',total,'receipt_id',p_id));
  return balance;
end $$;

create function public.request_barcode_cataloging(p_id uuid,p_site uuid,p_code text,p_description text,p_packs numeric)
returns uuid language plpgsql security definer set search_path='' as $$
declare old public.barcode_catalog_requests; payload jsonb; request uuid; r text;
begin
  r=public.user_role();
  if r is null or (r<>'admin' and p_site is distinct from public.user_headquarters_id()) then raise exception 'No puedes solicitar en esta sede'; end if;
  if not exists(select 1 from public.headquarters where id=p_site and is_active) then raise exception 'Sede inactiva'; end if;
  if p_id is null or p_code is null or p_code !~ '^[!-~]{1,128}$' or length(trim(coalesce(p_description,''))) not between 3 and 1000
    or p_packs is null or p_packs<=0 or p_packs>999999999 or p_packs<>trunc(p_packs) then raise exception 'Revisa codigo, descripcion y envases'; end if;
  payload=jsonb_build_object('site',p_site,'code',p_code,'description',p_description,'packs',p_packs);
  perform pg_advisory_xact_lock(90714001);
  select * into old from public.barcode_catalog_requests where id=p_id;
  if found then
    if old.actor_id<>auth.uid() or old.payload<>payload then raise exception 'Identificador reutilizado'; end if;
    return old.request_id;
  end if;
  insert into public.logistics_requests(headquarters_id,created_by,material,quantity,unit,notes)
    values(p_site,auth.uid(),'Catalogar: '||left(trim(p_description),140),p_packs,'envases',
      'PENDIENTE DE CATALOGACION. No se ha registrado stock. Codigo: '||p_code||E'\n'||p_description) returning id into request;
  insert into public.barcode_catalog_requests values(p_id,auth.uid(),payload,request);
  return request;
end $$;

create function public.create_inventory_record_once(p_id uuid,p_record jsonb)
returns uuid language plpgsql security definer set search_path='' as $$
declare old public.inventory_creation_requests; item uuid;
begin
  if public.user_role() is null or public.user_role() not in ('admin','editor','operator') or
    (public.user_role()<>'admin' and (p_record->>'headquarters_id')::uuid is distinct from public.user_headquarters_id()) then raise exception 'No puedes crear en esta sede'; end if;
  if p_id is null or coalesce((p_record->>'current_stock')::numeric,0)<>0 then raise exception 'Esta alta de catalogo debe empezar sin stock'; end if;
  perform pg_advisory_xact_lock(90714001);
  select * into old from public.inventory_creation_requests where id=p_id;
  if found then
    if old.actor_id<>auth.uid() or old.payload<>p_record then raise exception 'Identificador de alta reutilizado'; end if;
    return old.item_id;
  end if;
  item=public.create_inventory_record(p_record,null,0,null);
  insert into public.inventory_creation_requests values(p_id,auth.uid(),p_record,item);
  return item;
end $$;

revoke execute on function public.link_inventory_barcode(uuid,text,text,text,numeric),
  public.receive_inventory_barcode(uuid,uuid,numeric,text,date,jsonb,text),public.request_barcode_cataloging(uuid,uuid,text,text,numeric),
  public.create_inventory_record_once(uuid,jsonb) from public,anon,authenticated;
grant execute on function public.link_inventory_barcode(uuid,text,text,text,numeric),
  public.receive_inventory_barcode(uuid,uuid,numeric,text,date,jsonb,text),public.request_barcode_cataloging(uuid,uuid,text,text,numeric),
  public.create_inventory_record_once(uuid,jsonb) to authenticated;
notify pgrst,'reload schema';
$iae_ddl$;
insert into iae_internal.migrations(version) values('202609170001_barcode_receiving.sql');
end if;
end $iae_apply$;

do $iae_apply$ begin
if not exists(select 1 from iae_internal.migrations where version='202609180001_product_research.sql') then
execute $iae_ddl$-- Preserve user-reviewed provenance in the same transaction as the zero-stock creation.
-- This records a user's source declaration, not independent product verification.
create function public.create_inventory_record_from_product(p_id uuid,p_record jsonb,p_source jsonb)
returns uuid language plpgsql security definer set search_path='' as $$
declare item uuid; code text; checksum integer;
begin
  if p_id is null or jsonb_typeof(p_record) is distinct from 'object' then raise exception 'Alta de producto no valida'; end if;
  if p_source is null or jsonb_typeof(p_source)<>'object' or length(p_source::text)>512 or
    (select count(*) from jsonb_object_keys(p_source))<>4 or
    coalesce(p_source->>'provider','') not in ('upcitemdb','openfoodfacts') or
    p_source->'reviewed' is distinct from 'true'::jsonb or
    jsonb_typeof(p_source->'code') is distinct from 'string' or
    jsonb_typeof(p_source->'fetchedAt') is distinct from 'string' then
    raise exception 'Fuente revisada no valida';
  end if;
  code=p_source->>'code';
  if code !~ '^(\d{8}|\d{12}|\d{13}|\d{14})$' or code ~ '^0+$' then raise exception 'Codigo de producto no valido'; end if;
  select sum(substr(code,n,1)::integer * case when (length(code)-n)%2=1 then 3 else 1 end)
    into checksum from generate_series(1,length(code)-1) n;
  if (10-checksum%10)%10<>right(code,1)::integer then raise exception 'Codigo de producto no valido'; end if;
  if p_source->>'fetchedAt' !~ '^\d{4}-\d{2}-\d{2}T' then raise exception 'Fecha de consulta no valida'; end if;
  perform (p_source->>'fetchedAt')::timestamptz;
  perform pg_advisory_xact_lock(90714001);
  -- The existing RPC enforces role, site, field validation and exact-payload retries.
  item=public.create_inventory_record_once(p_id,p_record||jsonb_build_object('_online_source',p_source));
  if not exists(select 1 from public.inventory_item_history where item_id=item and event_type='online_product_review') then
    insert into public.inventory_item_history(item_id,actor_id,event_type,details)
      values(item,auth.uid(),'online_product_review',jsonb_build_object('source',p_source));
  end if;
  return item;
end $$;

revoke execute on function public.create_inventory_record_from_product(uuid,jsonb,jsonb) from public,anon,authenticated;
grant execute on function public.create_inventory_record_from_product(uuid,jsonb,jsonb) to authenticated;
notify pgrst,'reload schema';
$iae_ddl$;
insert into iae_internal.migrations(version) values('202609180001_product_research.sql');
end if;
end $iae_apply$;

do $iae_apply$ begin
if not exists(select 1 from iae_internal.migrations where version='202610010001_category_hierarchy.sql') then
execute $iae_ddl$alter table public.inventory_categories
  add column if not exists parent_code text references public.inventory_categories(code) on delete restrict;
create index if not exists inventory_categories_parent_idx on public.inventory_categories(parent_code);

create or replace function public.guard_category_parent() returns trigger
language plpgsql security definer set search_path='' as $$
begin
  perform pg_advisory_xact_lock(90714001);
  if new.parent_code=new.code or (new.parent_code is not null and exists(with recursive parents as (
    select code,parent_code from public.inventory_categories where code=new.parent_code
    union select c.code,c.parent_code from public.inventory_categories c join parents p on c.code=p.parent_code
  ) select 1 from parents where code=new.code)) then
    raise exception 'Una categoria no puede depender de si misma ni de una de sus subcategorias'
      using errcode='23514';
  end if;
  return new;
end $$;
drop trigger if exists guard_category_parent on public.inventory_categories;
create trigger guard_category_parent before insert or update on public.inventory_categories
for each row execute function public.guard_category_parent();
revoke all on function public.guard_category_parent() from public,anon,authenticated;

$iae_ddl$;
insert into iae_internal.migrations(version) values('202610010001_category_hierarchy.sql');
end if;
end $iae_apply$;

do $iae_apply$ begin
if not exists(select 1 from iae_internal.migrations where version='202610050001_uniformity_import.sql') then
execute $iae_ddl$alter table public.inventory_template_fields add column allowed_options jsonb
  check(allowed_options is null or jsonb_typeof(allowed_options)='array');
create or replace function public.validate_inventory_fields() returns trigger
language plpgsql security definer set search_path='' as $$
declare f record; values_json jsonb; val text;
begin
  if new.template_id is null then return new; end if;
  if new.category is distinct from (select category_code from public.inventory_templates where id=new.template_id) then raise exception 'Categoria y plantilla no coinciden'; end if;
  values_json=coalesce(new.technical_specs,'{}'::jsonb) || jsonb_build_object(
    'item_name',new.name,'name',new.name,'description',new.description,'subtype',new.subtype,'sku',new.sku,'serial_number',new.serial_number,
    'current_stock',new.current_stock,'minimum_stock',new.minimum_stock,'unit',new.unit,'expiration_date',new.expiration_date,
    'maintenance_due_at',new.maintenance_due_at,'location_id',new.location_id,'lot_code',new.lot_code,'is_consumable',new.is_consumable);
  for f in select d.field_key,d.field_type,d.options,a.allowed_options,a.is_required from public.inventory_template_fields a join public.inventory_fields d on d.id=a.field_id where a.template_id=new.template_id loop
    val=values_json->>f.field_key;
    if f.is_required and f.field_type<>'boolean' and (val is null or trim(val)='') then raise exception 'Falta campo obligatorio: %',f.field_key; end if;
    if val is null or val='' then continue; end if;
    if f.field_type='number' and val !~ '^-?[0-9]+(\.[0-9]+)?$' then raise exception 'Numero invalido: %',f.field_key; end if;
    if f.field_type='date' then perform val::date; end if;
    if f.field_type='boolean' and val not in ('true','false') then raise exception 'Booleano invalido: %',f.field_key; end if;
    if f.field_type='select' and (not (f.options ? val) or (f.allowed_options is not null and not f.allowed_options ? val)) then raise exception 'Opcion no disponible en esta ficha: %',f.field_key; end if;
  end loop;
  return new;
end $$;

create table public.uniformity_import_drafts (
  id uuid primary key default gen_random_uuid(),
  created_by uuid not null default auth.uid() references public.profiles(id),
  filename text not null check(length(filename) between 1 and 200),
  file_hash text not null check(file_hash ~ '^[a-f0-9]{64}$'),
  rows jsonb not null check(jsonb_typeof(rows)='array' and jsonb_array_length(rows) between 1 and 2000),
  created_at timestamptz not null default now()
);
create table public.uniformity_imports (
  id uuid primary key default gen_random_uuid(),
  draft_id uuid not null unique references public.uniformity_import_drafts(id),
  headquarters_id uuid not null references public.headquarters(id),
  location_id uuid references public.locations(id),
  container_id uuid references public.inventory_containers(id),
  content_hash text not null,
  article_count integer not null,
  total_quantity integer not null,
  created_by uuid not null references public.profiles(id),
  created_at timestamptz not null default now(),
  unique(headquarters_id,content_hash)
);
create table public.uniformity_import_lines (
  import_id uuid not null references public.uniformity_imports(id),
  item_id uuid not null unique references public.inventory_items(id),
  source text not null,
  quantity integer not null check(quantity>=0),
  primary key(import_id,item_id)
);
alter table public.uniformity_import_drafts enable row level security;
alter table public.uniformity_imports enable row level security;
alter table public.uniformity_import_lines enable row level security;
create policy uniformity_drafts_read on public.uniformity_import_drafts for select to authenticated using(public.user_role()='admin');
create policy uniformity_drafts_create on public.uniformity_import_drafts for insert to authenticated with check(public.user_role()='admin' and created_by=auth.uid());
create policy uniformity_imports_read on public.uniformity_imports for select to authenticated using(public.user_role()='admin');
create policy uniformity_import_lines_read on public.uniformity_import_lines for select to authenticated using(public.user_role()='admin');
revoke all on public.uniformity_import_drafts,public.uniformity_imports,public.uniformity_import_lines from public,anon,authenticated;
grant select on public.uniformity_import_drafts,public.uniformity_imports,public.uniformity_import_lines to authenticated;
grant insert(filename,file_hash,rows) on public.uniformity_import_drafts to authenticated;

create function public.import_uniformity_stock(p_draft_id uuid,p_headquarters_id uuid,p_location_id uuid default null,p_container_id uuid default null)
returns uuid language plpgsql security definer set search_path='' as $$
declare draft public.uniformity_import_drafts; batch public.uniformity_imports; entry jsonb; clean jsonb; fingerprint text; sizes jsonb;
  v_category_code text; v_template_code text; garment text; size text; amount integer; article uuid; template uuid; v_sku text; import_id uuid;
begin
  if public.user_role() is distinct from 'admin' then raise exception 'Solo administracion puede importar'; end if;
  perform pg_advisory_xact_lock(90714001);
  select * into draft from public.uniformity_import_drafts where id=p_draft_id and created_by=auth.uid();
  if not found then raise exception 'Vista previa no disponible. Analiza el archivo otra vez'; end if;
  select * into batch from public.uniformity_imports where draft_id=p_draft_id;
  if found then
    if batch.headquarters_id<>p_headquarters_id then raise exception 'Esta vista previa ya se importo en otra sede'; end if;
    if batch.location_id is distinct from p_location_id or batch.container_id is distinct from p_container_id then raise exception 'Esta vista previa ya se importo en otro destino. No se modifica la carga anterior'; end if;
    return batch.id;
  end if;
  if not exists(select 1 from public.headquarters where id=p_headquarters_id and is_active) then raise exception 'Sede no disponible'; end if;
  if p_location_id is not null and p_container_id is not null then raise exception 'Elige ubicacion o caja, no ambas'; end if;
  if p_location_id is not null and not exists(select 1 from public.locations where id=p_location_id and headquarters_id=p_headquarters_id and is_active) then raise exception 'Ubicacion no disponible en esta sede'; end if;
  if p_container_id is not null and not exists(select 1 from public.inventory_containers where id=p_container_id and headquarters_id=p_headquarters_id and is_active) then raise exception 'Caja no disponible en esta sede'; end if;
  if exists(select 1 from jsonb_array_elements(draft.rows) e where
    coalesce(e->>'section','') not in ('first','second') or length(trim(coalesce(e->>'garment',''))) not between 2 and 120 or
    coalesce(e->>'size','') not in ('XS','S','M','L','XL','XXL','SIN TALLA') or coalesce(e->>'quantity','') !~ '^[0-9]{1,7}$' or
    length(coalesce(e->>'source','')) not between 1 and 200) then raise exception 'Filas de importacion no validas'; end if;
  if exists(select 1 from jsonb_array_elements(draft.rows) e where (e->>'quantity')::integer>1000000) then raise exception 'Cantidad excesiva'; end if;
  if exists(select 1 from jsonb_array_elements(draft.rows) e group by e->>'section',e->>'garment',e->>'size' having count(*)>1) then raise exception 'Hay prendas y tallas duplicadas'; end if;
  select jsonb_agg(jsonb_build_object('section',e->>'section','garment',e->>'garment','size',e->>'size','quantity',(e->>'quantity')::integer)
    order by e->>'section',e->>'garment',e->>'size') into clean from jsonb_array_elements(draft.rows) e;
  fingerprint=md5(clean::text);
  select * into batch from public.uniformity_imports where headquarters_id=p_headquarters_id and content_hash=fingerprint;
  if found then
    if batch.location_id is distinct from p_location_id or batch.container_id is distinct from p_container_id then raise exception 'Este contenido ya se importo en otro destino. Usa movimientos para trasladar el stock'; end if;
    return batch.id;
  end if;

  insert into public.inventory_categories(code,name,parent_code) values('uniformidad','Uniformidad',null) on conflict(code) do nothing;
  insert into public.inventory_categories(code,name,parent_code) values
    ('uniformidad_primera','Primera uniformidad','uniformidad'),('uniformidad_segunda','Segunda uniformidad','uniformidad') on conflict(code) do nothing;
  if exists(select 1 from public.inventory_categories where (code='uniformidad' and parent_code is not null)
    or (code in ('uniformidad_primera','uniformidad_segunda') and parent_code is distinct from 'uniformidad')) then raise exception 'Las categorias existentes no coinciden con Uniformidad'; end if;
  insert into public.inventory_fields(field_key,label,field_type,options) values
    ('name','Nombre del articulo','text','[]'),('uniformidad_talla','Talla','select','["XS","S","M","L","XL","XXL","SIN TALLA"]'),
    ('current_stock','Stock inicial','number','[]') on conflict(field_key) do nothing;
  if exists(select 1 from public.inventory_fields where (field_key='name' and field_type<>'text') or
    (field_key='current_stock' and field_type<>'number') or (field_key='uniformidad_talla' and (field_type<>'select' or not options @> '["XS","S","M","L","XL","XXL","SIN TALLA"]'::jsonb))) then raise exception 'Los campos existentes son incompatibles con la importacion'; end if;
  insert into public.uniformity_imports(draft_id,headquarters_id,location_id,container_id,content_hash,article_count,total_quantity,created_by)
    select p_draft_id,p_headquarters_id,p_location_id,p_container_id,fingerprint,jsonb_array_length(clean),sum((e->>'quantity')::integer),auth.uid() from jsonb_array_elements(clean) e returning id into import_id;
  for entry in select * from jsonb_array_elements(draft.rows) loop
    garment=entry->>'garment'; size=entry->>'size'; amount=(entry->>'quantity')::integer;
    v_category_code=case when entry->>'section'='first' then 'uniformidad_primera' else 'uniformidad_segunda' end;
    v_template_code='uniformidad_'||md5((entry->>'section')||'|'||garment);
    v_sku='UNI-'||md5((entry->>'section')||'|'||garment||'|'||size);
    if exists(select 1 from public.inventory_items i where i.headquarters_id=p_headquarters_id and i.sku=v_sku) then
      raise exception 'Ya existe % talla % en esta sede. No se sobreescribe ni se suma stock; usa movimientos para actualizarlo',garment,size;
    end if;
    insert into public.inventory_templates(code,name,category_code,description) values(v_template_code,garment,v_category_code,'Uniformidad importada; existencias independientes por talla') on conflict(code) do nothing;
    select id into template from public.inventory_templates t where t.code=v_template_code and t.category_code=v_category_code;
    if template is null then raise exception 'La ficha existente tiene una categoria diferente'; end if;
    select jsonb_agg(e->>'size' order by e->>'size') into sizes from jsonb_array_elements(clean) e where e->>'section'=entry->>'section' and e->>'garment'=garment;
    insert into public.inventory_template_fields(template_id,field_id,field_key,label,field_type,options,is_required,sort_order,allowed_options)
      select template,f.id,f.field_key,f.label,f.field_type,f.options,f.field_key<>'current_stock',
        case f.field_key when 'name' then 0 when 'uniformidad_talla' then 1 else 2 end,
        case when f.field_key='uniformidad_talla' then sizes else null end
      from public.inventory_fields f where f.field_key in ('name','uniformidad_talla','current_stock') on conflict(template_id,field_key) do nothing;
    if exists(select 1 from public.inventory_template_fields where template_id=template and field_key='uniformidad_talla' and allowed_options is distinct from sizes) then
      raise exception 'Las tallas de la ficha % han cambiado. Revisa su configuracion antes de importar',garment;
    end if;
    article=public.create_inventory_record(jsonb_build_object('name',garment||' · '||size,'slug','uniformidad-'||p_headquarters_id||'-'||lower(v_sku),
      'template_id',template,'headquarters_id',p_headquarters_id,'location_id',p_location_id,'sku',v_sku,'unit','unidades',
      'current_stock',amount,'technical_specs',jsonb_build_object('uniformidad_talla',size),'lot_code','Carga inicial'),p_container_id,amount,'Importacion inicial de uniformidad');
    insert into public.uniformity_import_lines(import_id,item_id,source,quantity) values(import_id,article,entry->>'source',amount);
  end loop;
  return import_id;
end $$;
revoke all on function public.import_uniformity_stock(uuid,uuid,uuid,uuid) from public,anon,authenticated;
grant execute on function public.import_uniformity_stock(uuid,uuid,uuid,uuid) to authenticated;
notify pgrst, 'reload schema';
$iae_ddl$;
insert into iae_internal.migrations(version) values('202610050001_uniformity_import.sql');
end if;
end $iae_apply$;

