using(public.user_role()='admin' or id=public.portal_headquarters_id());

-- Personnel can exist before an Auth account is available; link accounts only by an explicit admin action.
create table public.volunteers (
  id uuid primary key default gen_random_uuid(),
  external_code text not null unique check(length(trim(external_code)) between 1 and 80),
  full_name text not null check(length(trim(full_name)) between 2 and 160),
  email text check(email is null or length(email)<=254),
  headquarters_id uuid not null references public.headquarters(id) on delete restrict,
  profile_id uuid unique references public.profiles(id) on delete restrict,
  is_active boolean not null default true,
  created_at timestamptz not null default now()
);
create index volunteers_site_name on public.volunteers(headquarters_id,full_name);
create table public.volunteer_deliveries (
  id uuid primary key,
  volunteer_id uuid not null references public.volunteers(id) on delete restrict,
  item_id uuid not null references public.inventory_items(id) on delete restrict,
  material text not null,
  size text,
  quantity integer not null check(quantity>0),
  returned_quantity integer not null default 0 check(returned_quantity>=0 and returned_quantity<=quantity),
  delivered_on date,
  historical boolean not null,
  source_position_id uuid references public.inventory_stock_positions(id),
  notes text not null,
  payload jsonb not null,
  created_by uuid not null references public.profiles(id),
  created_at timestamptz not null default now()
);
create index volunteer_deliveries_owner on public.volunteer_deliveries(volunteer_id,created_at desc);
create table public.volunteer_returns (
  id uuid primary key,
  delivery_id uuid not null references public.volunteer_deliveries(id),
  quantity integer not null check(quantity>0),
  destination_id uuid not null references public.inventory_stock_positions(id),
  notes text not null,
  created_by uuid not null references public.profiles(id),
  created_at timestamptz not null default now()
);
alter table public.volunteers enable row level security;
alter table public.volunteer_deliveries enable row level security;
alter table public.volunteer_returns enable row level security;
create policy volunteers_read on public.volunteers for select to authenticated
using(public.user_role()='admin' or (profile_id=auth.uid() and public.portal_headquarters_id() is not null));
create policy volunteer_deliveries_read on public.volunteer_deliveries for select to authenticated
using(exists(select 1 from public.volunteers v where v.id=volunteer_id));
create policy volunteer_returns_read on public.volunteer_returns for select to authenticated
using(exists(select 1 from public.volunteer_deliveries d where d.id=delivery_id));
revoke all on public.volunteers,public.volunteer_deliveries,public.volunteer_returns from public,anon,authenticated;
grant select on public.volunteers,public.volunteer_deliveries,public.volunteer_returns to authenticated;

create function public.save_volunteer(p_id uuid,p_code text,p_name text,p_email text,p_headquarters_id uuid,p_profile_id uuid default null)
returns uuid language plpgsql security definer set search_path='' as $$
declare result uuid;
begin
  if public.user_role() is distinct from 'admin' then raise exception 'Solo administracion puede gestionar voluntarios'; end if;
  perform pg_advisory_xact_lock(90714001);
  if not exists(select 1 from public.headquarters where id=p_headquarters_id and is_active) then raise exception 'Sede no disponible'; end if;
  if p_profile_id is not null and not exists(select 1 from public.profiles p join public.app_roles r on r.id=p.role_id
    where p.id=p_profile_id and p.is_active and (p.headquarters_id=p_headquarters_id or r.code='admin')) then raise exception 'El usuario no pertenece a esta sede o esta inactivo'; end if;
  if p_id is null then
    insert into public.volunteers(external_code,full_name,email,headquarters_id,profile_id)
      values(trim(p_code),trim(p_name),nullif(trim(p_email),''),p_headquarters_id,p_profile_id) returning id into result;
  else
    update public.volunteers set external_code=trim(p_code),full_name=trim(p_name),email=nullif(trim(p_email),''),headquarters_id=p_headquarters_id,profile_id=p_profile_id
      where id=p_id returning id into result;
    if result is null then raise exception 'Voluntario no encontrado'; end if;
  end if;
  return result;
end $$;

create function public.record_volunteer_delivery(p_id uuid,p_volunteer_id uuid,p_item_id uuid,p_quantity integer,p_historical boolean,p_delivered_on date,p_source_id uuid,p_notes text)
returns uuid language plpgsql security definer set search_path='' as $$
declare person public.volunteers; article public.inventory_items; src public.inventory_stock_positions; previous public.volunteer_deliveries; payload jsonb;
begin
  if public.user_role() is distinct from 'admin' then raise exception 'Solo administracion puede registrar entregas'; end if;
  if p_id is null or p_quantity is null or p_quantity not between 1 and 1000000 or p_historical is null or
    p_delivered_on>current_date or length(coalesce(p_notes,''))>2000 or (not p_historical and p_delivered_on is null) or
    (p_historical and p_source_id is not null) then raise exception 'Revisa cantidad, fecha y tipo de entrega'; end if;
  payload=jsonb_build_object('volunteer',p_volunteer_id,'item',p_item_id,'quantity',p_quantity,'historical',p_historical,'date',p_delivered_on,'source',p_source_id,'notes',p_notes);
  perform pg_advisory_xact_lock(90714001);
  select * into previous from public.volunteer_deliveries where id=p_id;
  if found then
    if previous.created_by<>auth.uid() or previous.payload<>payload then raise exception 'Identificador de entrega reutilizado con otros datos'; end if;
    return previous.id;
  end if;
  select * into person from public.volunteers where id=p_volunteer_id and is_active;
  if not found then raise exception 'Voluntario no disponible'; end if;
  select * into article from public.inventory_items where id=p_item_id and headquarters_id=person.headquarters_id;
  if not found then raise exception 'Articulo no disponible en la sede del voluntario'; end if;
  if not p_historical then
    if not exists(select 1 from public.headquarters where id=person.headquarters_id and is_active) then raise exception 'La sede esta inactiva'; end if;
    select * into src from public.inventory_stock_positions where id=p_source_id and item_id=p_item_id;
    if not found then raise exception 'Selecciona la existencia de origen'; end if;
    perform public.manage_inventory_stock(p_id,p_item_id,'out',src.id,src.lot_id,null,null,p_quantity,'Entrega a '||person.full_name||': '||coalesce(p_notes,''));
  end if;
  insert into public.volunteer_deliveries(id,volunteer_id,item_id,material,size,quantity,delivered_on,historical,source_position_id,notes,payload,created_by)
    values(p_id,person.id,article.id,article.name,article.technical_specs->>'uniformidad_talla',p_quantity,p_delivered_on,p_historical,p_source_id,coalesce(p_notes,''),payload,auth.uid());
  return p_id;
end $$;

create function public.return_volunteer_delivery(p_id uuid,p_delivery_id uuid,p_quantity integer,p_destination_id uuid,p_notes text)
returns uuid language plpgsql security definer set search_path='' as $$
declare delivery public.volunteer_deliveries; dest public.inventory_stock_positions; previous public.volunteer_returns;
begin
  if public.user_role() is distinct from 'admin' then raise exception 'Solo administracion puede registrar devoluciones'; end if;
  if p_id is null or p_quantity is null or p_quantity<=0 or length(trim(coalesce(p_notes,''))) not between 3 and 1800 then raise exception 'Indica cantidad positiva y motivo'; end if;
  perform pg_advisory_xact_lock(90714001);
  select * into previous from public.volunteer_returns where id=p_id;
  if found then
    if previous.delivery_id<>p_delivery_id or previous.quantity<>p_quantity or previous.destination_id<>p_destination_id or previous.notes is distinct from p_notes or previous.created_by<>auth.uid() then raise exception 'Identificador de devolucion reutilizado'; end if;
    return previous.id;
  end if;
  select * into delivery from public.volunteer_deliveries where id=p_delivery_id for update;
  if not found or p_quantity>delivery.quantity-delivery.returned_quantity then raise exception 'Cantidad superior al material pendiente de devolver'; end if;
  select * into dest from public.inventory_stock_positions where id=p_destination_id and item_id=delivery.item_id;
  if not found then raise exception 'El destino debe ser una existencia del mismo articulo'; end if;
  perform public.manage_inventory_stock(p_id,delivery.item_id,'in',null,dest.lot_id,dest.location_id,dest.container_id,p_quantity,'Devolucion de voluntario: '||p_notes);
  update public.volunteer_deliveries set returned_quantity=returned_quantity+p_quantity where id=delivery.id;
  insert into public.volunteer_returns(id,delivery_id,quantity,destination_id,notes,created_by) values(p_id,delivery.id,p_quantity,dest.id,p_notes,auth.uid());
  return p_id;
end $$;
revoke all on function public.save_volunteer(uuid,text,text,text,uuid,uuid),public.record_volunteer_delivery(uuid,uuid,uuid,integer,boolean,date,uuid,text),public.return_volunteer_delivery(uuid,uuid,integer,uuid,text) from public,anon,authenticated;
grant execute on function public.save_volunteer(uuid,text,text,text,uuid,uuid),public.record_volunteer_delivery(uuid,uuid,uuid,integer,boolean,date,uuid,text),public.return_volunteer_delivery(uuid,uuid,integer,uuid,text) to authenticated;
notify pgrst, 'reload schema';
$iae_ddl$;
insert into iae_internal.migrations(version) values('202610050002_volunteer_portal.sql');
end if;
end $iae_apply$;

do $iae_apply$ begin
if not exists(select 1 from iae_internal.migrations where version='202610060001_inventory_import.sql') then
execute $iae_ddl$create index inventory_import_sku_lookup on public.inventory_items(headquarters_id,lower(trim(sku)));
create index inventory_import_name_lookup on public.inventory_items(headquarters_id,category,lower(trim(name)));

create table public.inventory_import_drafts (
  id uuid primary key default gen_random_uuid(),
  created_by uuid not null default auth.uid() references public.profiles(id),
  created_at timestamptz not null default now(),
  filename text not null check(length(filename) between 1 and 200),
  reference text not null check(length(reference) between 3 and 80),
  -- Snapshot IDs: abandoned previews must not prevent deleting empty destinations.
  -- The executor checks the site and destination again on every confirmation.
  headquarters_id uuid not null,
  location_id uuid,
  container_id uuid,
  payload jsonb not null,
  plan jsonb not null,
  imported_at timestamptz,
  check(location_id is null or container_id is null)
);
create unique index inventory_import_receipt_once on public.inventory_import_drafts(headquarters_id,lower(reference)) where imported_at is not null;
alter table public.inventory_import_drafts enable row level security;
create policy inventory_import_drafts_read on public.inventory_import_drafts for select to authenticated using(public.user_role()='admin' and created_by=auth.uid());
revoke all on public.inventory_import_drafts from public,anon,authenticated;
grant select on public.inventory_import_drafts to authenticated;

-- Shared by preview and commit. Preview uses a subtransaction to run the real
-- constraints and stock functions, then rolls back *all* catalogue/stock writes.
-- PL/pgSQL local variables survive that rollback; only the plan is returned.
create function public.execute_inventory_import(p_payload jsonb,p_site uuid,p_location uuid,p_container uuid,p_reference text,p_preview boolean)
returns jsonb language plpgsql security definer set search_path='' as $$
#variable_conflict use_variable
declare
  r jsonb; f jsonb; category_name text; parent text; category_code text; codes text[]; ids uuid[];
  item public.inventory_items; template public.inventory_templates; field public.inventory_fields; lot public.inventory_stock_lots;
  template_name text; category_path text; new_item boolean; qty numeric; before_qty numeric; article uuid; lot_code text;
  sku text; seen uuid[]='{}'; key text; value text; field_type text; n integer=0; field_order integer;
  lines jsonb='[]'; categories jsonb='[]'; templates jsonb='[]'; fields jsonb='[]'; assignments jsonb='[]'; result jsonb;
begin
  if public.user_role() is distinct from 'admin' then raise exception 'Solo administracion puede importar'; end if;
  perform pg_advisory_xact_lock(90714001);
  if p_reference is null or length(trim(p_reference)) not between 3 and 80 then raise exception 'Indica una referencia de carga de 3 a 80 caracteres'; end if;
  if not exists(select 1 from public.headquarters where id=p_site and is_active) then raise exception 'Sede no disponible'; end if;
  if p_location is not null and p_container is not null then raise exception 'Elige ubicacion o caja, no ambas'; end if;
  if p_location is not null and not exists(select 1 from public.locations where id=p_location and headquarters_id=p_site and is_active) then raise exception 'Ubicacion no disponible en esta sede'; end if;
  if p_container is not null and not exists(select 1 from public.inventory_containers where id=p_container and headquarters_id=p_site and is_active) then raise exception 'Caja no disponible en esta sede'; end if;
  if jsonb_typeof(p_payload->'rows') is distinct from 'array' or jsonb_typeof(p_payload->'fields') is distinct from 'array' then raise exception 'Formato de importacion no valido'; end if;
  if jsonb_array_length(p_payload->'rows') not between 1 and 500 or jsonb_array_length(p_payload->'fields')>40 or octet_length(p_payload::text)>800000 then raise exception 'Maximo 500 articulos y 40 campos por carga'; end if;
  if exists(select 1 from jsonb_array_elements(p_payload->'fields') e group by e->>'key' having count(*)>1) then raise exception 'Hay claves de campo repetidas'; end if;
  begin
    for f in select * from jsonb_array_elements(p_payload->'fields') loop
      key=f->>'key'; field_type=f->>'type';
      if key is null or key !~ '^[a-z][a-z0-9_]{0,59}$' or length(coalesce(f->>'label','')) not between 1 and 120 or field_type is null or field_type not in ('text','textarea','number','date','boolean','select') then raise exception 'Definicion de campo no valida'; end if;
      if key in ('id','item_name','subtype','location_id','headquarters_id','category','template_id','maintenance_due_at') then raise exception 'Clave reservada: %',key; end if;
      if (key in ('name','sku','serial_number','unit','lot_code') and field_type<>'text') or (key in ('current_stock','minimum_stock') and field_type<>'number') or (key='expiration_date' and field_type<>'date') or (key='is_consumable' and field_type<>'boolean') or (key='description' and field_type not in ('text','textarea')) then raise exception 'Tipo incompatible para el campo %',key; end if;
      select * into field from public.inventory_fields where field_key=key;
      if found then
        if field.field_type<>field_type and not (key='description' and field.field_type in ('text','textarea')) then raise exception 'El campo % ya existe con tipo %. Revisa la asignacion de columnas',key,field.field_type; end if;
      else
        if field_type='select' then raise exception 'Crea primero el campo desplegable % y sus opciones en Campos',key; end if;
        insert into public.inventory_fields(field_key,label,field_type) values(key,f->>'label',field_type);
        fields=fields||jsonb_build_array((f->>'label')||' ['||key||', '||field_type||']');
      end if;
    end loop;
    for r in select * from jsonb_array_elements(p_payload->'rows') loop
      n=n+1; item=null; template=null; parent=null; category_code=null; category_path='';
      if jsonb_typeof(r->'category') is distinct from 'array' or jsonb_typeof(r->'specs') is distinct from 'object' then raise exception 'Fila %: categoria o campos no validos',n+1; end if;
      if jsonb_array_length(r->'category')>5 or coalesce(r->>'quantity','') !~ '^[0-9]+(\.[0-9]{1,3})?$' then raise exception 'Fila %: cantidad o categoria no valida',n+1; end if;
      qty=(r->>'quantity')::numeric;
      if qty>1000000 then raise exception 'Fila %: cantidad superior a 1000000',n+1; end if;
      if exists(select 1 from jsonb_each_text(r->'specs') s where length(s.value)>2000 or not exists(select 1 from jsonb_array_elements(p_payload->'fields') d where d->>'key'=s.key) or s.key in ('name','sku','current_stock','minimum_stock','unit','expiration_date','lot_code','is_consumable','description','serial_number')) then raise exception 'Fila %: campos desconocidos o reservados',n+1; end if;
      if coalesce(r->>'expiration_date','')<>'' and (r->>'expiration_date' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or to_char((r->>'expiration_date')::date,'YYYY-MM-DD')<>r->>'expiration_date') then raise exception 'Fila %: caducidad no valida',n+1; end if;
      if coalesce(r->>'minimum_stock','')<>'' and (r->>'minimum_stock' !~ '^[0-9]+(\.[0-9]{1,3})?$' or (r->>'minimum_stock')::numeric>1000000) then raise exception 'Fila %: stock minimo no valido',n+1; end if;
      if coalesce(r->>'is_consumable','')<>'' and r->>'is_consumable' not in ('true','false') then raise exception 'Fila %: fungible debe ser true o false',n+1; end if;
      if exists(select 1 from jsonb_each_text(r) e where e.key not in ('category','specs') and length(e.value)>2000) or length(coalesce(r->>'sku',''))>120 or length(coalesce(r->>'name',''))>200 or length(coalesce(r->>'unit',''))>40 or length(coalesce(r->>'lot_code',''))>120 then raise exception 'Fila %: texto demasiado largo',n+1; end if;
      sku=nullif(trim(r->>'sku'),'');
      if nullif(r->>'id','') is not null then
        select * into item from public.inventory_items where id=(r->>'id')::uuid and headquarters_id=p_site;
        if not found then raise exception 'Fila %: ID no disponible en la sede seleccionada',n+1; end if;
        if sku is not null and lower(item.sku) is distinct from lower(sku) then raise exception 'Fila %: ID y SKU no corresponden al mismo articulo',n+1; end if;
      elsif sku is not null then
        select array_agg(id order by id) into ids from public.inventory_items where headquarters_id=p_site and lower(trim(inventory_items.sku))=lower(sku);
        if cardinality(ids)>1 then raise exception 'Fila %: SKU duplicado en la sede. Indica el ID exacto del articulo',n+1; end if;
        select * into item from public.inventory_items where id=ids[1];
      end if;
      for category_name in select jsonb_array_elements_text(r->'category') loop
        if length(trim(category_name)) not between 1 and 120 then raise exception 'Fila %: nombre de categoria no valido',n+1; end if;
        select array_agg(code order by code) into codes from public.inventory_categories c where c.parent_code is not distinct from parent and (lower(trim(c.name))=lower(trim(category_name)) or c.code=category_name);
        if cardinality(codes)>1 then raise exception 'Fila %: categoria ambigua %. Usa su codigo',n+1,category_name; end if;
        category_code=codes[1];
        if category_code is null then
          category_code='imp_'||md5(coalesce(parent,'')||'/'||lower(trim(category_name)));
          insert into public.inventory_categories(code,name,parent_code) values(category_code,trim(category_name),parent);
          categories=categories||jsonb_build_array(category_path||trim(category_name));
        end if;
        category_path=category_path||(select name from public.inventory_categories where code=category_code)||' > ';
        parent=category_code;
      end loop;
      if item.id is null and sku is null and nullif(r->>'template','') is null then
        select array_agg(i.id order by i.id) into ids from public.inventory_items i where i.headquarters_id=p_site and lower(trim(i.name))=lower(trim(r->>'name')) and i.category=category_code
          and coalesce((select jsonb_object_agg(s.key,s.value) from jsonb_each_text(i.technical_specs) s where s.key not in ('name','item_name','current_stock','sku','unit','lot_code','expiration_date','serial_number','minimum_stock','is_consumable','description','location_id','subtype','maintenance_due_at')),'{}')=r->'specs';
        if cardinality(ids)>1 then raise exception 'Fila %: varios articulos coinciden. Indica SKU o ID',n+1; end if;
        select * into item from public.inventory_items where id=ids[1];
      end if;
      if item.id is not null then
        if category_code is not null and category_code is distinct from item.category then raise exception 'Fila %: categoria distinta a la del articulo identificado',n+1; end if;
        category_code=item.category;
        if nullif(r->>'template','') is null then select * into template from public.inventory_templates where id=item.template_id; end if;
      end if;
      if category_code is null then raise exception 'Fila %: un articulo nuevo necesita categoria y nombre, o un SKU/ID existente',n+1; end if;
      if template.id is null and nullif(r->>'template','') is null then
        select array_agg(t.id order by t.id) into ids from public.inventory_templates t where t.category_code=category_code
          and coalesce((select jsonb_agg(a.field_key order by a.field_key) from public.inventory_template_fields a where a.template_id=t.id
            and a.field_key not in ('name','item_name','current_stock','sku','unit','lot_code','expiration_date','serial_number','minimum_stock','is_consumable','description','location_id','subtype','maintenance_due_at')),'[]')
            =coalesce((select jsonb_agg(s.key order by s.key) from jsonb_each(r->'specs') s),'[]');
        if cardinality(ids)>1 then raise exception 'Fila %: varios tipos de ficha tienen estos campos. Indica el tipo o su codigo',n+1; end if;
        select * into template from public.inventory_templates where id=ids[1];
      end if;
      if template.id is null then
        template_name=coalesce(nullif(trim(r->>'template'),''),(select name from public.inventory_categories where code=category_code));
        if length(template_name) not between 1 and 120 then raise exception 'Fila %: tipo de articulo no valido',n+1; end if;
        select array_agg(id order by id) into ids from public.inventory_templates t where t.category_code=category_code and (lower(trim(t.name))=lower(template_name) or t.code=template_name);
        if cardinality(ids)>1 then raise exception 'Fila %: tipo de articulo ambiguo. Indica su codigo',n+1; end if;
        select * into template from public.inventory_templates where id=ids[1];
        if template.id is null then
          insert into public.inventory_templates(code,name,category_code) values('imp_'||md5(category_code||'/'||lower(template_name)),template_name,category_code) returning * into template;
          templates=templates||jsonb_build_array(template.name||' ['||category_code||']');
        end if;
      end if;
      if item.id is null and sku is null then
        -- Without an identifier, require exact characteristics, not just a shared type.
        select array_agg(i.id order by i.id) into ids from public.inventory_items i where i.headquarters_id=p_site and lower(trim(i.name))=lower(trim(r->>'name')) and i.category=category_code
          and i.template_id=template.id and coalesce((select jsonb_object_agg(s.key,s.value) from jsonb_each_text(i.technical_specs) s where s.key not in ('name','item_name','current_stock','sku','unit','lot_code','expiration_date','serial_number','minimum_stock','is_consumable','description','location_id','subtype','maintenance_due_at')),'{}')=r->'specs';
        if cardinality(ids)>1 then raise exception 'Fila %: varios articulos coinciden. Indica SKU o ID',n+1; end if;
        select * into item from public.inventory_items where id=ids[1];
        if item.id is null and exists(select 1 from public.inventory_items i where i.headquarters_id=p_site and lower(trim(i.name))=lower(trim(r->>'name')) and i.category=category_code) then raise exception 'Fila %: ese nombre ya existe con otras caracteristicas. Usa el SKU/ID existente o una nueva referencia SKU para otro producto',n+1; end if;
      end if;
      new_item=item.id is null;
      if not new_item then
        if item.template_id is distinct from template.id then raise exception 'Fila %: el tipo de ficha no coincide con el articulo',n+1; end if;
        if item.operational_status='retired' then raise exception 'Fila %: no se puede reponer un articulo retirado',n+1; end if;
        if nullif(r->>'name','') is not null and lower(trim(item.name))<>lower(trim(r->>'name')) then raise exception 'Fila %: el nombre no coincide con el SKU/ID. La importacion no modifica fichas existentes',n+1; end if;
        for key,value in select * from jsonb_each_text(r->'specs') loop
          if item.technical_specs->>key is distinct from value then raise exception 'Fila %: el campo % no coincide con el articulo existente',n+1,key; end if;
        end loop;
        if (nullif(r->>'unit','') is not null and r->>'unit' is distinct from item.unit) or
          (nullif(r->>'serial_number','') is not null and r->>'serial_number' is distinct from item.serial_number) or
          (nullif(r->>'minimum_stock','') is not null and (r->>'minimum_stock')::numeric is distinct from item.minimum_stock) or
          (nullif(r->>'is_consumable','') is not null and (r->>'is_consumable')::boolean is distinct from item.is_consumable) or
          (nullif(r->>'description','') is not null and r->>'description' is distinct from item.description) then raise exception 'Fila %: los datos no coinciden. El importador suma stock, no edita datos existentes',n+1; end if;
      elsif length(trim(coalesce(r->>'name',''))) not between 1 and 200 then raise exception 'Fila %: el articulo nuevo necesita un nombre',n+1;
      end if;
      field_order=coalesce((select max(sort_order)+1 from public.inventory_template_fields where template_id=template.id),0);
      for f in select * from jsonb_array_elements(p_payload->'fields') loop
        key=f->>'key';
        -- Empty custom cells are absent characteristics, not a request to alter a type.
        if key not in ('name','current_stock') and not (r ? key or r->'specs' ? key) then continue; end if;
        select * into field from public.inventory_fields where field_key=key;
        if not exists(select 1 from public.inventory_template_fields a where a.template_id=template.id and a.field_key=key) then
          insert into public.inventory_template_fields(template_id,field_id,field_key,label,field_type,options,sort_order) values(template.id,field.id,field.field_key,field.label,field.field_type,field.options,field_order);
          field_order=field_order+1;
          assignments=assignments||jsonb_build_array(template.name||': '||field.label||' ['||key||']');
        end if;
      end loop;
      lot_code=coalesce(nullif(trim(r->>'lot_code'),''),'IMP-'||substr(md5(lower(p_reference)),1,20));
      before_qty=coalesce(item.current_stock,0);
      if new_item then
        sku=coalesce(sku,'IMP-'||substr(md5(p_site::text||'/'||lower(p_reference)||'/'||n::text),1,20));
        article=public.create_inventory_record(jsonb_build_object('name',trim(r->>'name'),'slug','import-'||gen_random_uuid()::text,
          'sku',sku,'template_id',template.id,'headquarters_id',p_site,'location_id',p_location,'current_stock',qty,
          'unit',coalesce(nullif(r->>'unit',''),'unidades'),'technical_specs',r->'specs','lot_code',lot_code,
          'expiration_date',nullif(r->>'expiration_date',''),'serial_number',nullif(r->>'serial_number',''),
          'minimum_stock',coalesce(nullif(r->>'minimum_stock',''),'0')::numeric,'is_consumable',coalesce(nullif(r->>'is_consumable',''),'false')::boolean,
          'description',nullif(r->>'description','')),p_container,qty,'Importacion CSV/Excel: '||p_reference);
        select * into item from public.inventory_items where id=article;
      else
        article=item.id;
        if article=any(seen) then raise exception 'Fila %: el articulo se repite en el archivo. Agrupa las cantidades o separa las cargas por lote/destino',n+1; end if;
        if qty>0 then
          if nullif(r->>'expiration_date','') is null and exists(select 1 from public.inventory_template_fields where template_id=template.id and field_key='expiration_date' and is_required) then raise exception 'Fila %: falta la caducidad obligatoria del lote que entra',n+1; end if;
          select * into lot from public.inventory_stock_lots l where l.item_id=article and l.code=lot_code;
          if lot.id is not null then
            if lot.expiration_date is distinct from nullif(r->>'expiration_date','')::date or lot.variant_id is not null then raise exception 'Fila %: el lote ya existe con otra caducidad o marca. Usa otro lote o Recibir material',n+1; end if;
            perform public.manage_inventory_stock(gen_random_uuid(),article,'in',null,lot.id,p_location,p_container,qty,'Importacion CSV/Excel: '||p_reference);
          else
            perform public.manage_inventory_stock(gen_random_uuid(),article,'new_lot',null,null,p_location,p_container,qty,'Importacion CSV/Excel: '||p_reference,lot_code,nullif(r->>'expiration_date','')::date);
          end if;
        end if;
      end if;
      seen=array_append(seen,article);
      insert into public.inventory_item_history(item_id,actor_id,event_type,details) values(article,auth.uid(),'csv_import',jsonb_build_object('reference',p_reference,'row',n+1,'quantity',qty));
      lines=lines||jsonb_build_array(jsonb_build_object('row',n+1,'name',item.name,'sku',item.sku,'item_id',case when new_item then null else article end,
        'action',case when new_item then 'create' else 'add' end,'category',category_code,'template',template.name,'before',before_qty,'quantity',qty,'after',before_qty+qty,
        'lot',lot_code,'expiration',nullif(r->>'expiration_date',''),'specs',item.technical_specs,
        'details',jsonb_build_object('unit',item.unit,'serial_number',item.serial_number,'minimum_stock',item.minimum_stock,'is_consumable',item.is_consumable,'description',item.description)));
    end loop;
    result=jsonb_build_object('lines',lines,'categories',categories,'templates',templates,'fields',fields,'assignments',assignments);
    if p_preview then raise exception using errcode='PIV01',message='rollback import preview'; end if;
  exception when sqlstate 'PIV01' then
    if not p_preview then raise; end if;
  when others then
    raise exception 'Carga cancelada (fila %): %',n+1,sqlerrm;
  end;
  return result;
end $$;
revoke all on function public.execute_inventory_import(jsonb,uuid,uuid,uuid,text,boolean) from public,anon,authenticated;

create function public.preview_inventory_import(p_payload jsonb,p_site uuid,p_location uuid,p_container uuid,p_reference text,p_filename text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare result jsonb; draft_id uuid;
begin
  if public.user_role() is distinct from 'admin' then raise exception 'Solo administracion puede importar'; end if;
  perform pg_advisory_xact_lock(90714001);
  if exists(select 1 from public.inventory_import_drafts where headquarters_id=p_site and lower(reference)=lower(trim(p_reference)) and imported_at is not null) then raise exception 'Esta referencia de carga ya se ha importado en la sede. Para otra entrega utiliza una referencia diferente'; end if;
  result=public.execute_inventory_import(p_payload,p_site,p_location,p_container,trim(p_reference),true);
  insert into public.inventory_import_drafts(filename,reference,headquarters_id,location_id,container_id,payload,plan)
    values(p_filename,trim(p_reference),p_site,p_location,p_container,p_payload,result) returning id into draft_id;
  return jsonb_build_object('draftId',draft_id,'plan',result);
end $$;
create function public.confirm_inventory_import(p_draft uuid)
returns jsonb language plpgsql security definer set search_path='' as $$
declare draft public.inventory_import_drafts; result jsonb;
begin
  if public.user_role() is distinct from 'admin' then raise exception 'Solo administracion puede importar'; end if;
  perform pg_advisory_xact_lock(90714001);
  select * into draft from public.inventory_import_drafts where id=p_draft and created_by=auth.uid() for update;
  if not found then raise exception 'Vista previa no disponible'; end if;
  if draft.imported_at is not null then return draft.plan; end if;
  if draft.created_at<now()-interval '7 days' then raise exception 'La vista previa ha caducado. Vuelve a revisar el archivo'; end if;
  if exists(select 1 from public.inventory_import_drafts where headquarters_id=draft.headquarters_id and lower(reference)=lower(draft.reference) and imported_at is not null) then raise exception 'Esta referencia de carga ya se ha importado. No se duplica el stock'; end if;
  result=public.execute_inventory_import(draft.payload,draft.headquarters_id,draft.location_id,draft.container_id,draft.reference,false);
  if result is distinct from draft.plan then raise exception 'El catalogo o las existencias han cambiado desde la revision. No se ha importado nada: vuelve a generar la vista previa'; end if;
  update public.inventory_import_drafts set imported_at=now() where id=p_draft;
  return result;
end $$;
revoke all on function public.preview_inventory_import(jsonb,uuid,uuid,uuid,text,text),public.confirm_inventory_import(uuid) from public,anon,authenticated;
grant execute on function public.preview_inventory_import(jsonb,uuid,uuid,uuid,text,text),public.confirm_inventory_import(uuid) to authenticated;
notify pgrst, 'reload schema';
$iae_ddl$;
insert into iae_internal.migrations(version) values('202610060001_inventory_import.sql');
end if;
end $iae_apply$;

do $iae_apply$ begin
if not exists(select 1 from iae_internal.migrations where version='202610060002_member_accounts.sql') then
execute $iae_ddl$-- Administrators may have global access without a home headquarters.
alter table public.volunteers alter column headquarters_id drop not null;
create index volunteers_email_lookup on public.volunteers(lower(trim(email)));
create index volunteers_email_exact on public.volunteers(email);

create table public.member_imports (
  id uuid primary key,
  created_by uuid not null references public.profiles(id),
  filename text not null,
  payload jsonb not null,
  created_at timestamptz not null default now()
);
create table public.member_provision_requests (
  id uuid primary key default gen_random_uuid(),
  batch_id uuid not null references public.member_imports(id),
  row_number integer not null,
  email text not null,
  full_name text not null,
  headquarters_id uuid,
  role_code text not null,
  external_code text,
  legacy_volunteer_id uuid,
  is_logistics_contact boolean not null default false,
  profile_id uuid,
  state text not null default 'pending' check(state in ('pending','created','existing')),
  mail_status text not null default 'pending' check(mail_status in ('pending','sent','failed','not_needed')),
  last_error text,
  lease uuid,
  leased_until timestamptz,
  updated_at timestamptz not null default now(),
  unique(batch_id,email), unique(batch_id,row_number)
);
alter table public.member_imports enable row level security;
alter table public.member_provision_requests enable row level security;
create policy member_imports_read on public.member_imports for select to authenticated using(public.user_role()='admin' and created_by=auth.uid());
create policy member_requests_read on public.member_provision_requests for select to authenticated using(public.user_role()='admin' and exists(select 1 from public.member_imports b where b.id=batch_id and b.created_by=auth.uid()));
revoke all on public.member_imports,public.member_provision_requests from public,anon,authenticated;
grant select on public.member_imports,public.member_provision_requests to authenticated;

create function public.sync_profile_volunteer() returns trigger
language plpgsql security definer set search_path='' as $$
declare v public.volunteers; email_address text; legacy_ids uuid[]; request public.member_provision_requests; code text; member_name text;
begin
  select lower(trim(u.email)) into email_address from auth.users u where u.id=new.id;
  member_name=left(coalesce(nullif(trim(new.full_name),''),email_address,'Voluntario'),160);
  if length(member_name)<2 then member_name='Voluntario '||member_name; end if;
  select * into v from public.volunteers where profile_id=new.id;
  if v.id is null then
    select r.* into request from public.member_provision_requests r join auth.users u on u.id=new.id
      where r.id::text=to_jsonb(u)->'raw_app_meta_data'->>'iae_provision_request' and r.email=email_address and r.profile_id is null;
    if request.legacy_volunteer_id is not null then
      select * into v from public.volunteers where id=request.legacy_volunteer_id and profile_id is null for update;
      if not found then raise exception 'La ficha antigua ya tiene otra cuenta. Revisa el alta'; end if;
    else
      select array_agg(id order by id) into legacy_ids from public.volunteers
        where profile_id is null and email_address is not null and lower(trim(email))=email_address and headquarters_id is not distinct from new.headquarters_id;
      if cardinality(legacy_ids)=1 then select * into v from public.volunteers where id=legacy_ids[1] for update; end if;
    end if;
    code=coalesce(request.external_code,'VOL-'||new.id::text);
    if v.id is null then
      insert into public.volunteers(external_code,full_name,email,headquarters_id,profile_id,is_active)
      values(code,member_name,email_address,new.headquarters_id,new.id,new.is_active);
      return new;
    end if;
  end if;
  update public.volunteers set profile_id=new.id,full_name=member_name,
    email=email_address,headquarters_id=new.headquarters_id,is_active=new.is_active where id=v.id;
  return new;
end $$;
create trigger sync_profile_volunteer after insert or update of full_name,headquarters_id,is_active on public.profiles
for each row execute function public.sync_profile_volunteer();
revoke all on function public.sync_profile_volunteer() from public,anon,authenticated;

-- Reconcile existing accounts without inventing emails or losing historical deliveries.
update public.profiles set full_name=full_name;

create or replace function public.handle_new_user() returns trigger
language plpgsql security definer set search_path='' as $$
declare request public.member_provision_requests; role uuid;
begin
  select * into request from public.member_provision_requests
    where id::text=to_jsonb(new)->'raw_app_meta_data'->>'iae_provision_request' and email=lower(trim(new.email)) and profile_id is null;
  if request.id is not null then
    if (request.headquarters_id is null and request.role_code<>'admin') or (request.headquarters_id is not null and not exists(select 1 from public.headquarters where id=request.headquarters_id and is_active)) then raise exception 'Sede no disponible para el alta'; end if;
    select id into role from public.app_roles where code=request.role_code;
  else
    -- User-editable metadata never supplies roles or headquarters.
    select id into role from public.app_roles where code='volunteer';
  end if;
  insert into public.profiles(id,full_name,role_id,headquarters_id,is_active,is_logistics_contact)
    values(new.id,coalesce(request.full_name,left(coalesce(new.raw_user_meta_data->>'full_name',new.email,'Voluntario'),160)),role,
      request.headquarters_id,true,coalesce(request.is_logistics_contact,false));
  if request.id is not null then
    update public.member_provision_requests set profile_id=new.id,state='created',updated_at=now() where id=request.id;
  end if;
  return new;
end $$;
revoke all on function public.handle_new_user() from public,anon,authenticated;

create function public.sync_member_email() returns trigger language plpgsql security definer set search_path='' as $$
begin
  if new.email is distinct from old.email then
    update public.volunteers set email=lower(trim(new.email)) where profile_id=new.id;
  end if;
  return new;
end $$;
create trigger sync_member_email after update of email on auth.users for each row execute function public.sync_member_email();
revoke all on function public.sync_member_email() from public,anon,authenticated;

-- Changing name/base site in either screen changes the same person. Account links
-- cannot be removed or reassigned through the old volunteer creation RPC.
create or replace function public.save_volunteer(p_id uuid,p_code text,p_name text,p_email text,p_headquarters_id uuid,p_profile_id uuid default null)
returns uuid language plpgsql security definer set search_path='' as $$
declare v public.volunteers; profile public.profiles; result uuid; account_email text;
begin
  if public.user_role() is distinct from 'admin' then raise exception 'Solo administracion puede gestionar voluntarios'; end if;
  perform pg_advisory_xact_lock(90714002);
  if p_id is not null then select * into v from public.volunteers where id=p_id;
  elsif p_profile_id is not null then select * into v from public.volunteers where profile_id=p_profile_id; end if;
  if v.id is null or v.profile_id is null then raise exception 'Crea la cuenta con correo y codigo de activacion. No se pueden crear fichas sin usuario'; end if;
  if p_profile_id is not null and p_profile_id<>v.profile_id then raise exception 'No se puede cambiar la cuenta de una ficha'; end if;
  select * into profile from public.profiles where id=v.profile_id;
  if p_id is null and profile.headquarters_id is distinct from p_headquarters_id and not exists(select 1 from public.app_roles where id=profile.role_id and code='admin') then raise exception 'El usuario no pertenece a esta sede'; end if;
  if p_headquarters_id is not null and not exists(select 1 from public.headquarters where id=p_headquarters_id and is_active) then raise exception 'Sede no disponible'; end if;
  if p_headquarters_id is null and not exists(select 1 from public.app_roles where id=profile.role_id and code='admin') then raise exception 'Asigna una sede al voluntario'; end if;
  select lower(trim(email)) into account_email from auth.users where id=v.profile_id;
  if nullif(trim(p_email),'') is not null and lower(trim(p_email)) is distinct from account_email then raise exception 'El correo debe ser el de la cuenta de acceso'; end if;
  if length(trim(coalesce(p_name,''))) not between 2 and 160 or length(trim(coalesce(p_code,''))) not between 1 and 80 then raise exception 'Revisa nombre y codigo'; end if;
  update public.volunteers set external_code=trim(p_code) where id=v.id;
  update public.profiles set full_name=trim(p_name),headquarters_id=p_headquarters_id where id=v.profile_id;
  return v.id;
end $$;

create function public.preview_member_accounts(p_emails jsonb) returns table(email text,existing boolean)
language plpgsql stable security definer set search_path='' as $$
begin
  if public.user_role() is distinct from 'admin' then raise exception 'Solo administracion puede revisar usuarios'; end if;
  if jsonb_typeof(p_emails) is distinct from 'array' then raise exception 'Correos no validos'; end if;
  if jsonb_array_length(p_emails) not between 1 and 500 or octet_length(p_emails::text)>140000 then raise exception 'Maximo 500 correos'; end if;
  return query select lower(trim(e.value)),exists(select 1 from auth.users u where lower(trim(u.email))=lower(trim(e.value)))
    from jsonb_array_elements_text(p_emails) e(value);
end $$;
revoke all on function public.preview_member_accounts(jsonb) from public,anon,authenticated;
grant execute on function public.preview_member_accounts(jsonb) to authenticated;

create function public.prepare_member_accounts(p_id uuid,p_filename text,p_rows jsonb) returns uuid
language plpgsql security definer set search_path='' as $$
declare r jsonb; n integer=0; email_address text; ids uuid[]; account_id uuid; legacy public.volunteers; site uuid; role text; code text; existing public.member_imports;
begin
  if public.user_role() is distinct from 'admin' then raise exception 'Solo administracion puede dar de alta usuarios'; end if;
  perform pg_advisory_xact_lock(90714002);
  select * into existing from public.member_imports where id=p_id;
  if found then
    if existing.created_by<>auth.uid() or existing.payload<>p_rows then raise exception 'Identificador de carga reutilizado'; end if;
    return existing.id;
  end if;
  if p_id is null or length(coalesce(p_filename,'')) not between 1 and 200 or jsonb_typeof(p_rows) is distinct from 'array' then raise exception 'Archivo no valido'; end if;
  if jsonb_array_length(p_rows) not between 1 and 500 or octet_length(p_rows::text)>600000 then raise exception 'Maximo 500 usuarios por carga'; end if;
  if exists(select 1 from jsonb_array_elements(p_rows) e group by lower(trim(e->>'email')) having count(*)>1) then raise exception 'Hay correos repetidos en el archivo'; end if;
  if exists(select 1 from jsonb_array_elements(p_rows) e where nullif(trim(e->>'code'),'') is not null group by trim(e->>'code') having count(*)>1) then raise exception 'Hay codigos de voluntario repetidos'; end if;
  insert into public.member_imports(id,created_by,filename,payload) values(p_id,auth.uid(),p_filename,p_rows);
  for r in select * from jsonb_array_elements(p_rows) loop
    n=n+1; legacy=null; account_id=null;
    email_address=lower(trim(r->>'email')); site=nullif(r->>'site','')::uuid; role=coalesce(r->>'role','volunteer'); code=nullif(trim(r->>'code'),'');
    if email_address is null or length(email_address)>254 or email_address !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' or length(trim(coalesce(r->>'name',''))) not between 2 and 160 then raise exception 'Fila %: revisa correo y nombre',n+1; end if;
    if role not in ('admin','editor','reader','volunteer') or (site is null and role<>'admin') or (site is not null and not exists(select 1 from public.headquarters where id=site and is_active)) then raise exception 'Fila %: rol o sede no disponibles',n+1; end if;
    if length(coalesce(code,''))>80 then raise exception 'Fila %: codigo demasiado largo',n+1; end if;
    select array_agg(id) into ids from auth.users where lower(trim(email))=email_address;
    if cardinality(ids)>1 then raise exception 'Fila %: correo ambiguo en Auth',n+1; end if;
    account_id=ids[1];
    if nullif(r->>'volunteer_id','') is not null then
      select * into legacy from public.volunteers where id=(r->>'volunteer_id')::uuid and profile_id is null;
      if not found then raise exception 'Fila %: ficha antigua no disponible',n+1; end if;
    else
      select array_agg(id order by id) into ids from public.volunteers where profile_id is null and (lower(trim(email))=email_address or (code is not null and external_code=code));
      if cardinality(ids)>1 then raise exception 'Fila %: varias fichas antiguas coinciden. Revisa sus correos y codigos',n+1; end if;
      select * into legacy from public.volunteers where id=ids[1];
      if legacy.id is not null and nullif(trim(legacy.email),'') is not null and lower(trim(legacy.email))<>email_address then raise exception 'Fila %: el codigo pertenece a otro correo',n+1; end if;
    end if;
    if legacy.id is not null and legacy.headquarters_id is distinct from site then raise exception 'Fila %: la sede no coincide con la ficha antigua',n+1; end if;
    if code is not null and exists(select 1 from public.volunteers where external_code=code and id is distinct from legacy.id and profile_id is distinct from account_id) then raise exception 'Fila %: codigo ya asignado a otra persona',n+1; end if;
    insert into public.member_provision_requests(batch_id,row_number,email,full_name,headquarters_id,role_code,external_code,legacy_volunteer_id,is_logistics_contact,profile_id,state)
      values(p_id,n+1,email_address,trim(r->>'name'),site,role,coalesce(code,legacy.external_code),legacy.id,role<>'volunteer' and coalesce((r->>'logistics')::boolean,false),account_id,case when account_id is null then 'pending' else 'existing' end);
  end loop;
  return p_id;
end $$;

create function public.claim_member_provision(p_id uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare r public.member_provision_requests; owner uuid; account_id uuid; v public.volunteers; legacy public.volunteers; ready boolean; token uuid;
begin
  if public.user_role() is distinct from 'admin' then raise exception 'Solo administracion puede dar de alta usuarios'; end if;
  perform pg_advisory_xact_lock(90714002);
  select * into r from public.member_provision_requests where id=p_id for update;
  if not found or not exists(select 1 from public.member_imports where id=r.batch_id and created_by=auth.uid()) then raise exception 'Alta no disponible'; end if;
  if r.mail_status in ('sent','not_needed') then return jsonb_build_object('done',true); end if;
  if r.leased_until>now() then raise exception 'Esta fila se esta procesando. Espera dos minutos antes de reintentar'; end if;
  if r.headquarters_id is not null and not exists(select 1 from public.headquarters where id=r.headquarters_id and is_active) then raise exception 'La sede ya no esta disponible'; end if;
  select id,(coalesce(to_jsonb(u)->>'encrypted_password','')<>'') into account_id,ready from auth.users u where lower(trim(u.email))=r.email;
  if account_id is not null then
    if not exists(select 1 from public.profiles where id=account_id and is_active) then raise exception 'La cuenta esta inactiva. Revisala en Usuarios antes de continuar'; end if;
    select * into v from public.volunteers where profile_id=account_id;
    if r.legacy_volunteer_id is not null and v.id is distinct from r.legacy_volunteer_id then
      select * into legacy from public.volunteers where id=r.legacy_volunteer_id and profile_id is null for update;
      if legacy.id is null or v.headquarters_id is distinct from legacy.headquarters_id then raise exception 'Revisa la cuenta y sede antes de vincular el historial antiguo'; end if;
      update public.volunteer_deliveries set volunteer_id=legacy.id where volunteer_id=v.id;
      delete from public.volunteers where id=v.id;
      update public.volunteers set profile_id=account_id,full_name=v.full_name,email=r.email,is_active=v.is_active where id=legacy.id;
    end if;
    update public.member_provision_requests set profile_id=account_id,state=case when state='created' then state else 'existing' end,
      mail_status=case when ready then 'not_needed' else mail_status end,updated_at=now() where id=r.id;
    if ready then return jsonb_build_object('done',true); end if;
  end if;
  token=gen_random_uuid();
  update public.member_provision_requests set lease=token,leased_until=now()+interval '2 minutes',last_error=null where id=r.id;
  return jsonb_build_object('done',false,'token',token,'email',r.email,'profile_id',account_id,'request_id',r.id);
end $$;
create function public.finish_member_provision(p_id uuid,p_lease uuid,p_sent boolean,p_error text default null) returns void
language plpgsql security definer set search_path='' as $$
begin
  if public.user_role() is distinct from 'admin' then raise exception 'Solo administracion puede dar de alta usuarios'; end if;
  update public.member_provision_requests r set mail_status=case when p_sent then 'sent' else 'failed' end,last_error=left(p_error,500),lease=null,leased_until=null,updated_at=now()
  where r.id=p_id and r.lease=p_lease and exists(select 1 from public.member_imports b where b.id=r.batch_id and b.created_by=auth.uid());
  if not found then raise exception 'La operacion ha cambiado. Recarga el estado de la importacion'; end if;
end $$;
revoke all on function public.prepare_member_accounts(uuid,text,jsonb),public.claim_member_provision(uuid),public.finish_member_provision(uuid,uuid,boolean,text) from public,anon,authenticated;
grant execute on function public.prepare_member_accounts(uuid,text,jsonb),public.claim_member_provision(uuid),public.finish_member_provision(uuid,uuid,boolean,text) to authenticated;
notify pgrst, 'reload schema';
$iae_ddl$;
insert into iae_internal.migrations(version) values('202610060002_member_accounts.sql');
end if;
end $iae_apply$;

do $iae_apply$ begin
if not exists(select 1 from iae_internal.migrations where version='202610060003_size_catalog.sql') then
execute $iae_ddl$-- Garment templates created by the uniformity importer identify a product, not
-- a generic category. Keep item IDs as stock variants so existing QR codes,
-- deliveries, barcodes and stock history remain valid. Never group by name.
create or replace view public.inventory_catalog_items
with (security_invoker = true) as
with classified as (
  select i.*, t.name as garment_name,
    coalesce(t.code ~ '^uniformidad_[a-f0-9]{32}$'
      and nullif(btrim(i.technical_specs->>'uniformidad_talla'), '') is not null, false) as is_size_group
  from public.inventory_items i
  left join public.inventory_templates t on t.id=i.template_id
), grouped as (
  select
    (array_agg(id order by created_at, id))[1] as id,
    array_agg(id order by created_at, id) as item_ids,
    case when is_size_group then max(garment_name) else max(name) end as name,
    headquarters_id, category, unit, is_size_group,
    case when is_size_group then count(distinct technical_specs->>'uniformidad_talla') else 0 end as size_count,
    string_agg(name, ' ') as search_names,
    max(subtype) as subtype,
    sum(current_stock) as current_stock,
    sum(minimum_stock) as minimum_stock,
    case when bool_or(status='low') then 'low'
      when bool_or(status='maintenance') then 'maintenance' else 'ok' end as base_status,
    min(expiration_date) filter (where current_stock>0) as expiration_date,
    min(maintenance_due_at) as maintenance_due_at,
    case when count(distinct operational_status)=1 then max(operational_status) else 'mixed' end as operational_status,
    array_agg(distinct operational_status) as operational_statuses,
    max(created_at) as created_at,
    jsonb_agg(jsonb_build_object('id',id,'name',name,'size',technical_specs->>'uniformidad_talla',
      'quantity',current_stock,'status',status,'expiration_date',expiration_date,
      'operational_status',operational_status) order by created_at,id) as variants
  from classified
  group by case when is_size_group then template_id else id end,
    headquarters_id, category, unit, is_size_group
)
select id,item_ids,name,headquarters_id,category,unit,is_size_group,size_count,
  name || ' ' || search_names as search_text,subtype,current_stock,minimum_stock,
  case when expiration_date < (now() at time zone 'Europe/Madrid')::date then 'expired'
    else base_status end as status,
  expiration_date,maintenance_due_at,operational_status,operational_statuses,created_at,variants
from grouped;

revoke all on public.inventory_catalog_items from public,anon,authenticated;
grant select on public.inventory_catalog_items to authenticated;
comment on view public.inventory_catalog_items is
  'RLS-preserving catalogue: one garment per headquarters/category/unit, with item IDs retained as size variants. No stock mutation.';
notify pgrst, 'reload schema';
$iae_ddl$;
insert into iae_internal.migrations(version) values('202610060003_size_catalog.sql');
end if;
end $iae_apply$;
commit;
